const cfg=window.VASE_VOW_CONFIG;
document.querySelectorAll('[data-price]').forEach(el=>el.textContent=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(cfg.priceUSD));
document.querySelectorAll('[data-pay]').forEach(a=>a.addEventListener('click',()=>{const u=new URL(cfg.checkoutUrl);if(u.protocol!=='https:'||!(u.hostname==='gumroad.com'||u.hostname.endsWith('.gumroad.com')))return;for(const k of ['utm_source','utm_medium','utm_campaign','utm_content']){const v=new URLSearchParams(location.search).get(k);if(v)u.searchParams.set(k,v.slice(0,100))}a.href=u.href}));
const dialog=document.querySelector('#page-dialog');let lastFocus;
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{lastFocus=b;const im=document.querySelector('#page-image');im.src=b.dataset.page;im.alt=b.dataset.label;document.querySelector('#page-title').textContent=b.dataset.label;dialog.showModal();dialog.querySelector('.close').focus()}));
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const sticky=document.querySelector('.purchase-sticky');let cardVisible=true;function stickyState(){sticky.hidden=cardVisible||matchMedia('(min-width:761px)').matches}new IntersectionObserver(es=>{cardVisible=es[0].isIntersecting;stickyState()},{threshold:0}).observe(document.querySelector('.order-card [data-pay]'));window.addEventListener('resize',stickyState);
